function renderBatch(force=false){const batch=state.batch||{items:[],totals:{}};const totals=batch.totals||{};const activity=batch.activity||{};const activityNode=byId("batch-activity");const running=activity.state==="analyzing";if(activityNode){const elapsed=eta(activity.elapsed_seconds||0);const remaining=activity.eta_seconds==null?"calculating":eta(activity.eta_seconds);const sourceProgress=activity.sources_total?` • Sources ${activity.sources_completed||0}/${activity.sources_total}`:"";const itemProgress=activity.items_total?` • Items ${activity.items_completed||0}/${activity.items_total}`:"";const current=activity.current_item||activity.current_source;activityNode.dataset.state=activity.state||"idle";activityNode.textContent=running?`${activity.message||"Analyzing batch"}${sourceProgress}${itemProgress} • Elapsed ${elapsed} • ETA ${remaining}${current?` • Current: ${current}`:""}`:activity.state==="failed"?`Batch analysis failed: ${activity.error||activity.message||"Unknown error"}`:activity.state==="completed"?`${activity.message||"Batch analysis complete"} • Elapsed ${elapsed}`:"Ready to analyze a batch"}const analyzeButton=byId("batch-analyze");if(analyzeButton){analyzeButton.disabled=running;analyzeButton.textContent=running?"Analyzing…":"Analyze batch"}if(!byId("batch-destination").value&&document.activeElement!==byId("batch-destination"))byId("batch-destination").value=batch.shared_settings?.destination||state.settings.default_download_folder||"";if(batch.filename_template&&document.activeElement!==byId("batch-filename"))byId("batch-filename").value=batch.filename_template;byId("batch-count").textContent=`${totals.selected||0} selected`;const duration=totals.duration_seconds==null?`${totals.duration_known_count||0}/${totals.selected||0} durations known`:formatDuration(totals.duration_seconds);const size=totals.size_bytes==null?`${totals.size_known_count||0}/${totals.selected||0} sizes known`:fileSize(totals.size_bytes,totals.size_is_estimate);byId("batch-totals").textContent=batch.items?.length?`${totals.items||0} items • ${totals.ready||0} ready • ${totals.exceptions||0} need attention • ${duration} • ${size}`:"No batch analyzed";byId("batch-commit").disabled=!totals.selected||!!totals.exceptions;byId("batch-commit").title=totals.exceptions?"Resolve or skip every selected exception before adding jobs":"";const signature=batchStructureSignature(batch);if(!force&&signature===lastBatchStructureSignature)return;const exceptions=(batch.items||[]).filter(item=>item.selected&&item.status!=="ready"&&item.status!=="skipped");byId("batch-exceptions").innerHTML=exceptions.length?`<h3>${exceptions.length} need attention</h3><div class="batch-review-hint">Choose an available option for only that item, skip it, or revise the shared settings and apply them again.</div>${exceptions.map(batchExceptionHtml).join("")}`:"";byId("batch-items").innerHTML=(batch.items||[]).map(batchItemHtml).join("");bindBatchItems();lastBatchStructureSignature=signature}
function batchItemHtml(item){const issue=(item.issues||[]).map(value=>value.message).join(" • ");const meta=[item.status,item.duration_seconds==null?"Duration unavailable":formatDuration(item.duration_seconds),item.size_bytes==null?"Size unavailable":fileSize(item.size_bytes,item.size_is_estimate)].join(" • ");return`<div class="batch-item" data-item="${escapeHtml(item.item_id)}" draggable="true"><input class="batch-item-select" type="checkbox" ${item.selected?"checked":""} aria-label="Select batch item"><span class="batch-grip">⋮⋮</span><div><div class="batch-item-title">${escapeHtml(item.index+". "+(item.title||item.source_url))}</div><div class="batch-item-meta">${escapeHtml(meta)}</div><div class="batch-item-preview">${escapeHtml(item.filename_preview||"")}</div>${issue?`<div class="batch-issue">${escapeHtml(issue)}</div>`:""}</div><span>${item.playlist_index?`#${item.playlist_index}`:""}</span></div>`}
function batchVideoChoices(item){const streams=item.analysis?.video_streams||[];const options=streams.map(stream=>{const parts=[stream.resolution_family,stream.fps?`${stream.fps} FPS`:"",stream.codec||"",stream.container||"",stream.bitrate?`${stream.bitrate} Kbps`:""];return`<option value="${escapeHtml(stream.stream_id)}">${escapeHtml(parts.filter(Boolean).join(" • "))}</option>`}).join("");const audio=item.analysis?.audio_streams?.length?`<option value="audio_only">Audio only</option>`:"";return`${audio}${options}`}
