function batchConfiguration(){return{requested_quality:byId("batch-quality").value,requested_audio_languages:batchLanguages(byId("batch-audio-languages").value),requested_subtitle_languages:batchLanguages(byId("batch-subtitle-languages").value),shared_settings:batchSharedSettings(),filename_template:byId("batch-filename").value}}
