function diagnosticLine(event){const stamp=new Date(Number(event.at||0)*1000).toLocaleString();const payload=event.payload&&Object.keys(event.payload).length?` ${JSON.stringify(event.payload)}`:"";return`[${stamp}] ${String(event.level||"info").toUpperCase()} ${event.kind}${event.message?` - ${event.message}`:""}${payload}`}
async function loadDiagnostics(){if(diagnosticsLoading)return[];diagnosticsLoading=true;try{const scope=byId("diagnostics-scope")?.value==="all"?"all":"session";const result=await api(`/api/diagnostics?limit=20000&scope=${scope}`);const events=result.events||[];const log=byId("diagnostics-log");const nearBottom=log.scrollHeight-log.scrollTop-log.clientHeight<48;const earlier=Number(result.earlier_session_events||0);const scopeText=scope==="all"?"all recorded sessions":"this session only";const earlierText=scope==="session"&&earlier?` • ${earlier} event${earlier===1?"":"s"} from earlier sessions are kept but not shown`:"";byId("diagnostics-summary").textContent=`${events.length} event${events.length===1?"":"s"} • ${scopeText} • live${earlierText}`;log.textContent=events.map(diagnosticLine).join("\n")||(scope==="session"?"No diagnostic events recorded in this session yet.":"No diagnostic events recorded.");if(nearBottom)log.scrollTop=log.scrollHeight;return events}finally{diagnosticsLoading=false}}
async function openDiagnostics(){await loadDiagnostics();const dialog=byId("diagnostics-window");if(dialog.showModal)dialog.showModal();else dialog.setAttribute("open","")}
function historyTime(value){const date=new Date(Number(value||0)*1000);return Number.isNaN(date.getTime())?"Unknown date":date.toLocaleString()}
