async function loadHistory(){if(historyLoading)return;historyLoading=true;try{const query=encodeURIComponent(byId("history-search")?.value||"");const result=await api(`/api/history?q=${query}`);const items=result.items||[];byId("history-summary").textContent=`${items.length} history entr${items.length===1?"y":"ies"}`;byId("history-items").innerHTML=items.map(historyHtml).join("")||`<div class="empty">No completed downloads in history.</div>`;byId("history-items").querySelectorAll("[data-history-action]").forEach(button=>button.onclick=async()=>{const row=button.closest("[data-history]");const id=row.dataset.history;const action=button.dataset.historyAction;if(action==="copy"){const item=items.find(value=>value.history_id===id);await copyText(item?.source_url||"")}else if(action==="open")await api(`/api/history/${id}/open`,{method:"POST"});else if(action==="folder")await api(`/api/history/${id}/open-folder`,{method:"POST"});else if(action==="redownload"){await api(`/api/history/${id}/redownload`,{method:"POST"});await refresh(true);document.querySelector('[data-tab="main"]').click()}else if(action==="remove"){await api(`/api/history/${id}`,{method:"DELETE"});await loadHistory()}})}finally{historyLoading=false}}
document.querySelectorAll(".tab").forEach(tab=>tab.onclick=()=>{document.querySelectorAll(".tab,.panel").forEach(x=>x.classList.remove("active"));tab.classList.add("active");byId(`${tab.dataset.tab}-tab`).classList.add("active");if(tab.dataset.tab==="history")loadHistory()});
