async function smartAdd(text,analyze=true,addDuplicates=false){const result=await api("/api/jobs/smart-add",{method:"POST",body:JSON.stringify({text,add_duplicates:addDuplicates})});if(!result.recognized)throw new Error("No valid web media URL was found");pendingDuplicates=result.duplicates||[];byId("duplicate-bar").hidden=!pendingDuplicates.length;byId("duplicate-message").textContent=pendingDuplicates.length?`${pendingDuplicates.length} duplicate URL${pendingDuplicates.length===1?"":"s"} skipped`:"";await refresh(true);if(analyze&&result.jobs.length){await Promise.all(result.jobs.map(job=>api(`/api/jobs/${job.job_id}/analyze`,{method:"POST"})));await refresh(true)}return result}
