byId("delete-all").onclick=async()=>{const ids=state.jobs.map(job=>job.job_id);if(!ids.length){showNotice("There are no download cards to remove","info");return}if(!window.confirm(`Remove ${ids.length} download card(s)? Downloaded files are kept on disk.`))return;const button=byId("delete-all");button.disabled=true;try{const result=await api("/api/jobs/bulk",{method:"POST",body:JSON.stringify({job_ids:ids,action:"delete"})});const failed=(result.results||[]).filter(item=>!item.ok);await refresh(true);showNotice(failed.length?`Removed ${ids.length-failed.length} of ${ids.length} cards; ${failed.length} could not be removed`:`Removed ${ids.length} download card(s)`,failed.length?"error":"success",failed.length?0:5000)}catch(e){showNotice(`Delete all failed: ${e.message}`,"error",0)}finally{button.disabled=false}};
