document.addEventListener("keydown",async e=>{if(e.key==="Escape"){closeDrawer();const detector=byId("detector-window");if(detector?.open){await closeDetector();return}document.querySelectorAll(".card-menu-panel").forEach(panel=>panel.hidden=true);return}const typing=e.target.matches("input,textarea,select");if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="l"){e.preventDefault();byId("main-url").focus();byId("main-url").select();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="n"){e.preventDefault();byId("add-more").click();return}if((e.ctrlKey||e.metaKey)&&e.key==="Enter"){e.preventDefault();byId("analyze-main").click();return}if(!typing&&e.key==="/"){e.preventDefault();byId("main-url").focus();return}if(!selectedJob||typing)return;const job=state.jobs.find(item=>item.job_id===selectedJob);if(!job)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="d"&&job.status==="ready"){e.preventDefault();await api(`/api/jobs/${job.job_id}/start`,{method:"POST"});await refresh();return}if(e.code==="Space"&&["downloading","paused"].includes(job.status)){e.preventDefault();await api(`/api/jobs/${job.job_id}/${job.status==="paused"?"resume":"pause"}`,{method:"POST"});await refresh()}if(e.key==="Delete"&&["queued","unanalyzed","ready","stopped","failed","unresolved","unavailable","dependency_repair"].includes(job.status)&&window.confirm("Remove selected job?")){await api(`/api/jobs/${job.job_id}`,{method:"DELETE"});await refresh()}});
document.addEventListener("click",e=>{if(!e.target.closest(".card-menu,.card-menu-panel")){document.querySelectorAll(".card-menu-panel").forEach(panel=>panel.hidden=true);queueMicrotask(flushDeferredJobRender)}});
document.addEventListener("focusout",()=>setTimeout(flushDeferredJobRender,0));
document.addEventListener("dragover",e=>{if(e.dataTransfer?.types?.includes("Files")||e.dataTransfer?.types?.includes("text/uri-list"))e.preventDefault()});
document.addEventListener("drop",async e=>{if(e.target.closest(".job-card"))return;const file=e.dataTransfer?.files?.[0];const uri=e.dataTransfer?.getData("text/uri-list")||e.dataTransfer?.getData("text/plain")||"";if(file&&file.name.toLowerCase().endsWith(".txt")){e.preventDefault();await smartAdd(await file.text(),false)}else if(uri){e.preventDefault();await smartAdd(uri,true)}});
const STATUS_LABELS={unresolved:"Could not resolve media",unavailable:"Unavailable",auth_required:"Authentication required",dependency_repair:"Dependency repair required"};
function statusLabel(job){return STATUS_LABELS[job.status]||null}
function destinationButton(job){const info=job.destination_info||{};const available=!!info.available;const reason=available?`Open ${info.destination||""}`:(info.reason||"Destination is unavailable");return `<button class="open-destination"${available?"":" disabled"} title="${escapeHtml(reason)}">Open destination folder</button>`}
function detectorButton(job){const available=!!state.detector?.available;return `<button class="detect"${available?"":" disabled"} title="${available?"Open this page in Media Detector":"Media Detector requires Chromium"}">Open in Media Detector</button>`}
function actions(job){return `${primaryActions(job)}${destinationButton(job)}${detectorButton(job)}`}
function thumbnailStateText(job){const state_=job.thumbnail_embed_result||"not_attempted";const detail=job.thumbnail_embed_detail||"";if(state_==="embedded")return `Embedded: ${detail||"source thumbnail written into the media"}`;if(state_==="disabled")return "Disabled for this download";if(state_==="not_attempted")return "Will be attempted when the download completes";return `${state_.replace(/_/g," ")}${detail?": "+detail:""}`}
function thumbnailSettings(job){const s=job.settings;const source=job.thumbnail_source_url||job.analysis?.thumbnail_url||"";const preview=source?`<div class="artwork-preview"><img src="${escapeHtml(source)}" alt=""><span>${escapeHtml(source)}</span></div>`:`<div class="artwork-preview empty">This source did not expose a public thumbnail or poster</div>`;return `<label>Embed source thumbnail<input id="job-thumbnail" type="checkbox" ${s.embed_thumbnail?"checked":""}></label>${preview}<label>Add &quot;Downloaded by VideoHaul.&quot; to the comment tag<input id="job-comment-tag" type="checkbox" ${s.tag_download_comment!==false?"checked":""}></label><div class="artwork-state">${escapeHtml(thumbnailStateText(job))}</div>`}
function candidateFacts(candidate){const rows=[];const unknown="Unavailable";rows.push(["Type",candidate.media_kind==="hls"?"HLS stream":candidate.media_kind==="dash"?"DASH stream":candidate.media_kind==="audio"?"Audio":"Direct file"]);rows.push(["Duration",candidate.duration_seconds!=null?formatDuration(candidate.duration_seconds):"Duration unavailable"]);rows.push(["Resolution",candidate.width&&candidate.height?`${candidate.width}x${candidate.height}`:candidate.height?`${candidate.height}p`:unknown]);rows.push(["FPS",candidate.fps!=null?String(candidate.fps):unknown]);rows.push(["Video codec",candidate.video_codec||unknown]);rows.push(["Audio codec",candidate.audio_codec||unknown]);rows.push(["Dynamic range",candidate.hdr_mode||unknown]);rows.push(["Container",candidate.container||candidate.mime_type||unknown]);rows.push(["Bitrate",candidate.bitrate!=null?`${Math.round(candidate.bitrate/1000)} kbps`:unknown]);rows.push(["Size",fileSize(candidate.filesize_bytes,candidate.filesize_is_estimate)]);rows.push(["Host",candidate.host||unknown]);rows.push(["Live",candidate.is_live?"Live":"VOD"]);rows.push(["Frame depth",String(candidate.frame_depth||0)]);rows.push(["Found via",String(candidate.discovery_channel||candidate.discovery_method||unknown).replace(/[+_]/g," ")]);rows.push(["Verification",candidate.verification_state||"unverified"]);if(candidate.variant_count)rows.push(["Variants",`${candidate.variant_count} stream${candidate.variant_count===1?"":"s"}`]);if(candidate.sniffed_type)rows.push(["Detected by body",`${candidate.sniffed_type.toUpperCase()} despite ${escapeHtml(candidate.mime_type||"no content type")}`]);if(candidate.suggested_filename)rows.push(["Filename",candidate.suggested_filename]);if(candidate.segment_activity)rows.push(["Segments observed",String(candidate.segment_activity)]);if(candidate.split_audio_url)rows.push(["Audio","Separate audio stream"]);if(candidate.language)rows.push(["Language",candidate.language]);if(candidate.expiry_if_known)rows.push(["Expires",new Date(candidate.expiry_if_known*1000).toLocaleString()]);if(candidate.has_required_headers)rows.push(["Request context","Required headers preserved internally"]);return rows.map(([k,v])=>`<div class="fact"><span>${escapeHtml(k)}</span><strong>${escapeHtml(v)}</strong></div>`).join("")}
function variantRows(candidate){if(!candidate.variants||!candidate.variants.length)return"";const rows=candidate.variants.map(v=>{const res=v.width&&v.height?`${v.width}x${v.height}`:v.height?`${v.height}p`:"Resolution unavailable";const fps=v.fps!=null?`${v.fps} FPS`:"FPS unavailable";const codec=v.codec||"Codec unavailable";const rate=v.bitrate!=null?`${Math.round(v.bitrate/1000)} kbps`:"Bitrate unavailable";const dur=v.duration_seconds!=null?formatDuration(v.duration_seconds):"Duration unavailable";const size=fileSize(v.filesize_bytes,v.filesize_is_estimate);return `<tr><td>${escapeHtml(res)}</td><td>${escapeHtml(fps)}</td><td>${escapeHtml(codec)}</td><td>${escapeHtml(rate)}</td><td>${escapeHtml(dur)}</td><td>${escapeHtml(size)}</td></tr>`}).join("");return `<details class="candidate-variants"><summary>${candidate.variants.length} stream variant(s)</summary><table class="stream-table"><tr><th>Resolution</th><th>FPS</th><th>Codec</th><th>Bitrate</th><th>Duration</th><th>Size</th></tr>${rows}</table></details>`}
function candidateSummary(candidate){const unknown="Unavailable";const bits=[];bits.push(candidate.media_kind==="hls"?"HLS":candidate.media_kind==="dash"?"DASH":candidate.media_kind==="audio"?"Audio":(candidate.container||"File").toUpperCase());bits.push(candidate.duration_seconds!=null?formatDuration(candidate.duration_seconds):"Duration unavailable");bits.push(candidate.width&&candidate.height?`${candidate.width}x${candidate.height}`:candidate.height?`${candidate.height}p`:unknown);bits.push(candidate.bitrate!=null?`${Math.round(candidate.bitrate/1000)} kbps`:"Bitrate unavailable");bits.push(fileSize(candidate.filesize_bytes,candidate.filesize_is_estimate));if(candidate.variant_count)bits.push(`${candidate.variant_count} variants`);if(candidate.grouped_candidate_count>1)bits.push(`${candidate.grouped_candidate_count} related manifests grouped`);return bits.join(" \u2022 ")}
function candidateName(candidate){return candidate.suggested_filename||candidate.title||candidate.page_title||(String(candidate.final_url||candidate.discovered_url||"").split("/").pop()||"Detected media").split("?")[0]}
function candidateHtml(candidate){const expanded=expandedCandidates.has(candidate.candidate_id);const badge=candidate.likely_main_media?`<span class="badge main">Likely main media</span>`:"";const rejectedBadge=candidate.rejected?`<span class="badge rejected">Rejected</span>`:"";const evidence=(candidate.confidence_evidence||[]).map(line=>`<li>${escapeHtml(line)}</li>`).join("");const detail=expanded?`<div class="candidate-url">${escapeHtml(candidate.final_url||candidate.discovered_url||"")}${candidate.url_carries_secrets?`<span class="secret-note">authorization parameters hidden</span>`:""}</div><div class="candidate-facts">${candidateFacts(candidate)}</div>${variantRows(candidate)}<details class="candidate-evidence"><summary>Why this ranking</summary><ul>${evidence}</ul></details>`:"";const actionButtons=candidate.rejected?`<button data-candidate-action="restore">Restore</button>`:`<button data-candidate-action="adopt" class="primary">Add to VideoHaul</button><button data-candidate-action="download" class="primary">Download</button><button data-candidate-action="preview">Preview in VLC</button><button data-candidate-action="preview-full">Open full stream in VLC</button><button data-candidate-action="copy">Copy URL</button><button data-candidate-action="reject">Reject</button>`;return `<div class="candidate${expanded?" expanded":""}${candidate.rejected?" rejected":""}" data-candidate="${escapeHtml(candidate.candidate_id)}"><div class="candidate-head"><button class="candidate-toggle" data-candidate-action="toggle" aria-expanded="${expanded}">${expanded?"\u25be":"\u25b8"}</button><strong>${escapeHtml(candidateName(candidate))}</strong>${badge}${rejectedBadge}</div><div class="candidate-summary">${escapeHtml(candidateSummary(candidate))}</div>${detail}<div class="candidate-actions">${actionButtons}</div></div>`}
function renderDetector(session){const host=byId("detector-body");if(!host)return;const all=session.candidates||[];const rejectedCount=all.filter(item=>item.rejected).length;const candidates=detectorShowRejected?all:all.filter(item=>!item.rejected);const summary=byId("detector-summary");if(summary)summary.textContent=`${[String(session.stage||"starting").replace(/_/g," "),session.message||""].filter(Boolean).join(" \u2022 ")} \u2022 ${candidates.length} candidate(s)${rejectedCount?` \u2022 ${rejectedCount} rejected`:""} \u2022 ${session.frames_seen||0} frame(s) \u2022 ${session.network_events_seen||0} network event(s)`;const title=byId("detector-page");if(title)title.textContent=session.page_url||"";const toggle=byId("detector-rejected");if(toggle){toggle.hidden=!rejectedCount;toggle.textContent=detectorShowRejected?`Hide rejected (${rejectedCount})`:`Show rejected (${rejectedCount})`}if(!candidates.length){host.innerHTML=session.active?`<div class="empty">Watching this page for media. Interact with the page normally \u2014 press Play, choose a server, accept cookies \u2014 and candidates appear here as they are observed.</div>`:`<div class="empty">No media candidates were observed on this page. The page loaded, so this is an unresolved source rather than an unavailable one.</div>`;return}host.innerHTML=candidates.map(candidateHtml).join("");bindCandidates(session)}
function bindCandidates(session){document.querySelectorAll("#detector-body .candidate").forEach(node=>{const candidateId=node.dataset.candidate;const candidate=(session.candidates||[]).find(item=>item.candidate_id===candidateId);node.querySelectorAll("[data-candidate-action]").forEach(button=>{button.onclick=async()=>{const action=button.dataset.candidateAction;const original=button.textContent;button.disabled=true;try{if(action==="toggle"){if(expandedCandidates.has(candidateId))expandedCandidates.delete(candidateId);else expandedCandidates.add(candidateId);renderDetector(session);return}else if(action==="reject"||action==="restore"){await api(`/api/detector/sessions/${session.session_id}/candidates/${candidateId}/${action}`,{method:"POST"});renderDetector(await api(`/api/detector/sessions/${session.session_id}`));showNotice(action==="reject"?"Candidate rejected":"Candidate restored","success");return}else if(action==="copy"){const revealed=await api(`/api/detector/sessions/${session.session_id}/candidates/${candidateId}/reveal-url`,{method:"POST"});await copyText(revealed.url||"");showNotice(candidate.url_carries_secrets?"Candidate URL copied \u2014 it contains authorization parameters, share it carefully":"Candidate URL copied","success")}else if(action==="adopt"||action==="download"){button.textContent=action==="download"?"Starting download...":"Adding...";const result=await api(`/api/detector/sessions/${session.session_id}/candidates/${candidateId}/adopt`,{method:"POST",body:JSON.stringify({job_id:session.job_id||"",start:action==="download"})});showNotice(action==="download"?(result.started?"Candidate download started":"Candidate is already downloading"):(result.already_adopted?"This candidate is already a VideoHaul job":"Candidate added to VideoHaul"),"success");await refresh(true)}else{const full=action==="preview-full";const result=await api(`/api/detector/sessions/${session.session_id}/candidates/${candidateId}/preview`,{method:"POST",body:JSON.stringify({full_stream:full})});showNotice(result.detail||"Preview launched","success")}}catch(e){showNotice(e.message,"error",8000)}finally{button.disabled=false;button.textContent=original}}})})}
async function loadDetector(){if(detectorLoading||!detectorSessionId)return;detectorLoading=true;try{const session=await api(`/api/detector/sessions/${detectorSessionId}`);renderDetector(session)}catch(e){showNotice(`Media Detector unavailable: ${e.message}`,"error",0)}finally{detectorLoading=false}}
async function openDetectorFor(jobId,url){try{const session=await api("/api/detector/sessions",{method:"POST",body:JSON.stringify({job_id:jobId||"",url:url||"",mode:"interactive",headless:false})});detectorSessionId=session.session_id;const dialog=byId("detector-window");if(dialog&&!dialog.open)dialog.showModal();renderDetector(session)}catch(e){showNotice(`Media Detector could not start: ${e.message}`,"error",0)}}
async function closeDetector(){const dialog=byId("detector-window");if(dialog?.open)dialog.close();if(detectorSessionId){try{await api(`/api/detector/sessions/${detectorSessionId}/close`,{method:"POST"})}catch(e){}detectorSessionId=null}}
function scheduleEventRefresh(){if(eventRefreshTimer)return;eventRefreshTimer=setTimeout(()=>{eventRefreshTimer=null;refresh()},120)}
function connectEvents(){if(!window.EventSource)return;try{if(eventSource)eventSource.close();eventSource=new EventSource(`/api/events?last_event_id=${lastEventId||0}`)}catch(e){eventStreamConnected=false;return}eventSource.onopen=()=>{eventStreamConnected=true;eventReconnectDelay=1000};eventSource.onmessage=event=>{if(event.lastEventId)lastEventId=Number(event.lastEventId)||lastEventId;scheduleEventRefresh()};for(const kind of ["job_added","job_updated","job_deleted","progress","jobs_reordered","settings_updated","collapse_all","bandwidth_updated","history_added","history_deleted","history_cleared","history_redownload","detector_candidate_adopted"])eventSource.addEventListener(kind,event=>{if(event.lastEventId)lastEventId=Number(event.lastEventId)||lastEventId;scheduleEventRefresh()});eventSource.addEventListener("resync_required",()=>{lastEventId=0;refresh(true)});eventSource.onerror=()=>{eventStreamConnected=false;if(eventSource){eventSource.close();eventSource=null}setTimeout(connectEvents,eventReconnectDelay);eventReconnectDelay=Math.min(eventReconnectDelay*2,15000)}}

function renderDependencyHealth(report){const host=byId("dependency-health");if(!host)return;const rows=(report.tools||[]).map(tool=>{const optional=tool.optional?" (optional)":"";const status=tool.healthy?`<span class="ok">Healthy</span>`:`<span class="bad">${escapeHtml(tool.detail||"Repair required")}</span>`;const version=tool.version?escapeHtml(tool.version):"";return `<tr><td>${escapeHtml(tool.name)}${optional}</td><td>${status}</td><td>${version}</td><td>${escapeHtml(tool.source||"")}</td></tr>`}).join("");host.innerHTML=`<table>${rows}</table><div>${report.healthy?"All required engines are healthy":`Repair required: ${escapeHtml((report.repair_required||[]).join(", "))}`}</div>`}
async function checkDependencyHealth(){try{renderDependencyHealth(await api("/api/dependencies"))}catch(e){showNotice(`Dependency health unavailable: ${e.message}`,"error",0)}}
async function dependencyAction(path,label){const name=byId("dependency-name").value;try{const result=await api(`/api/dependencies/${path}`,{method:"POST",body:JSON.stringify({name})});showNotice(`${label} ${name}: ${result.state}${result.detail?` - ${result.detail}`:""}`,result.state==="updated"||result.state==="rolled_back"?"success":"error",0);await checkDependencyHealth()}catch(e){showNotice(`${label} failed: ${e.message}`,"error",0)}}
async function checkApplicationUpdates(){const host=byId("update-status");try{const result=await api("/api/updates");if(!host)return;if(result.state==="disabled")host.textContent="Update checks are disabled in Settings";else if(result.state==="not_configured")host.textContent=`VideoHaul ${result.current_version} - no update source is configured for this build`;else if(result.state==="unreachable")host.textContent=`VideoHaul ${result.current_version} - update check could not reach the update source`;else if(result.update_available)host.textContent=`VideoHaul ${result.available_version} is available (currently ${result.current_version})`;else host.textContent=`VideoHaul ${result.current_version} is up to date`}catch(e){if(host)host.textContent="Update check could not run"}}
async function exportDiagnosticReport(){try{const report=await api("/api/diagnostics/export");const text=JSON.stringify(report,null,2);const blob=new Blob([text],{type:"application/json"});const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download=`videohaul-diagnostics-${new Date().toISOString().replace(/[:.]/g,"-")}.json`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);showNotice("Diagnostic report exported","success")}catch(e){showNotice(`Diagnostic export failed: ${e.message}`,"error",0)}}

window.addEventListener("unhandledrejection",event=>reportUnhandledUiError(event.reason,"Unhandled action"));
window.addEventListener("error",event=>reportUnhandledUiError(event.error||event.message,"UI error"));
setInterval(()=>{if(!eventStreamConnected)refresh().catch(error=>reportUnhandledUiError(error,"refresh"))},1000);
setInterval(()=>{if(eventStreamConnected)refresh().catch(error=>reportUnhandledUiError(error,"refresh"))},5000);
setInterval(()=>{if(state.jobs.some(job=>["analyzing","downloading","finalizing"].includes(job.status)))updateLiveCards();if(state.batch?.activity?.state==="analyzing")renderBatch()},1000);
setInterval(()=>{const dialog=byId("diagnostics-window");if(dialog?.open)loadDiagnostics()},1000);
setInterval(()=>{const dialog=byId("detector-window");if(dialog?.open&&detectorSessionId)loadDetector()},1200);
refresh().then(()=>{connectEvents();if(state.settings?.app_update_checks!==false)setTimeout(()=>checkApplicationUpdates().catch(()=>{}),3000)});
